import math

def P(n):
    """Calculates P(n) = n^3 + 4n^2 + 6n + 4."""
    return n**3 + 4*n**2 + 6*n + 4

def get_prime_factorization(k):
    """Returns a dictionary of prime factors and their exponents for k."""
    factors = {}
    d = 2
    temp = k
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def check_divisibility(n):
    """Checks if P(n) divides 20^(n+1)."""
    if n < 0:
        return False

    Pn = P(n)

    if Pn == 1: # Only happens for n=-2, but we check n >= 0
        return True

    factors = get_prime_factorization(Pn)

    # Maximum exponents available in 20^(n+1) = 2^(2n+2) * 5^(n+1)
    max_exp_2 = 2 * n + 2
    max_exp_5 = n + 1

    for p, exponent in factors.items():
        if p != 2 and p != 5:
            # Pn has a prime factor other than 2 or 5
            return False

        if p == 2:
            if exponent > max_exp_2:
                return False

        elif p == 5:
            if exponent > max_exp_5:
                return False

    return True

# Brute force search for small n
# We test up to n=50 to see if there are more solutions.
results = {}
solutions = []
for n in range(51):
    if check_divisibility(n):
        solutions.append(n)
        results[n] = "Solution"
    else:
        results[n] = "Fail"

print("Solutions found:", solutions)

# Outputting the verification for small cases up to n=10
print("\nVerification for n=0 to 10:")
for n in range(11):
    is_sol = check_divisibility(n)
    print(f"n={n}: P(n)={P(n)}, Divides 20^{n+1}? {'Yes' if is_sol else 'No'}")
